import{z as n,x as o,o as A,c as d,q as t,j as i,D as e,d as l,s as r,S as s,b as a}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"小模型的数据配比","description":"","frontmatter":{"title":"小模型的数据配比","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/synthetic-small-model-mix.md","filePath":"llm/synthetic-small-model-mix.md","lastUpdated":1791413859000}'),m={name:"llm/synthetic-small-model-mix.md"};function p(C,E,D,h,F,c){const B=o("Mermaid");return A(),d("div",null,[E[2]||(E[2]=t('<h1 id="小模型的数据配比" tabindex="-1">小模型的数据配比 <a class="header-anchor" href="#小模型的数据配比" aria-label="Permalink to &quot;小模型的数据配比&quot;">​</a></h1><div class="epigraph"><p>小模型不是缩一号的大模型：容量更小，对坏样本更不宽容，对好配方更敏感——配比在小模型上是一等决策。</p><footer>—— 据 Mukherjee 等 Orca；Gunasekar 等 Textbooks；Abdin 等 Phi-3 整理</footer></div><p><a href="/llm/synthetic-diversity-metrics">上一课</a>定下覆盖怎么量；本课回答配比问题：合成与真实、各能力域之间，份额怎么分。这件事在小模型上被推到极端——<a href="/llm/synthetic-pretrain">合成数据在预训练中的位置</a>讲过合成是补丁不是主食，<a href="/llm/textbook-synthetic">教科书式合成</a>给过「高密度合成是有硬上限的调料」的结论。小模型让这些结论的每一个词都更重：它既没有容量吸收坏样本，也没有冗余稀释好配方。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>小模型的配比与<a href="/llm/data-mixture-laws">配比定律与领域配比</a>的大模型图景有两处结构性不同。其一，噪声敏感度：大模型有容量装下噪声样本，损失被平均掉；小模型的每一分容量都要花在刀刃上，质量过滤的档位必须更紧——大模型配比里能容忍的合成占比，直接搬到小模型常常失败。其二，风格吸收：小模型更容易学表面模式，合成数据的教师风格会被更深地烙进去，多教师、去风格化在小模型上不是可选优化。矛盾在于：小模型恰恰是蒸馏与合成的最大受益者——<a href="/llm/reasoning-distill-small">推理蒸馏到小模型</a>证明过滤后的长链能把小模型推过原本的规模线。收益与风险同源，配比就是在这对矛盾里找平衡点。<span class="marginnote">小模型对噪声敏感可以类比小背包：大背包随手塞，混进几件坏东西不碍事；小背包每一寸都要精挑，塞进一件废品就得挤掉一件有用的。配比在小模型上是一等决策，根源就是背包太小。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>配比按三个粒度定。能力域粒度：验证强的域（数学、代码）合成占比可以高——拦截率撑得住；开放域占比压低并以真实锚点兜底，沿用预训练侧「有源改写优于无源生成」的口径。阶段粒度：占比是训练阶段的函数——中期可以把高密度合成抬高（学技能），末段用真实数据退火（对齐分布）；倒序会让模型先学坏再难改。<span class="marginnote">「末段真实退火」可以翻译成：训练快收尾时把数据换回真实分布，让模型最后学的是真实世界的语言。若倒过来——先用真实再用合成收尾——模型交卷时满口教师风格，反而不像见过真实文本。</span>教师粒度：单教师的份额设上限，配比表按教师版本记账；教师升级时旧份额不自动顺延——教师换了，它那部分数据要重过滤。</p><p>规模是配比的隐藏维度：用小代理扫出来的最优配比不能直接平移到目标规模，<a href="/llm/proxy-model-experiments">小模型代理实验</a>的假阳性口径（数据制度不同）在合成数据上尤其常见——代理模型学合成的效率与目标模型不同构，方向性结论至少要在两个规模各验一遍。<span class="marginnote">初学者容易以为小模型上扫出的最优配比能直接搬到目标规模。代理模型学合成数据的效率与目标模型不同构：小代理觉得划算的配方，大模型可能根本不需要——这是数据制度不同造成的假阳性，不是调参手气问题。</span></p>',8)),(A(),i(s,null,{default:e(()=>[r(B,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20DOM%5B%22%E8%83%BD%E5%8A%9B%E5%9F%9F%EF%BC%9A%E9%AA%8C%E8%AF%81%E5%BC%BA%E4%B8%8E%E5%BC%80%E6%94%BE%E5%9F%9F%22%5D%20--%3E%20R1%5B%22%E5%9F%9F%E5%86%85%E5%90%88%E6%88%90%E4%B8%8E%E7%9C%9F%E5%AE%9E%E4%BB%BD%E9%A2%9D%22%5D%0A%20%20R1%20--%3E%20STAGE%5B%22%E9%98%B6%E6%AE%B5%E8%AE%A1%E5%88%92%EF%BC%9A%E4%B8%AD%E6%9C%9F%E6%8A%AC%E5%8D%87%EF%BC%8C%E6%9C%AB%E6%AE%B5%E7%9C%9F%E5%AE%9E%E9%80%80%E7%81%AB%22%5D%0A%20%20STAGE%20--%3E%20TEA%5B%22%E6%95%99%E5%B8%88%E4%BB%BD%E9%A2%9D%E4%B8%8A%E9%99%90%E4%B8%8E%E7%89%88%E6%9C%AC%E8%AE%B0%E8%B4%A6%22%5D%0A%20%20TEA%20--%3E%20PROXY%5B%22%E5%B0%8F%E4%BB%A3%E7%90%86%E6%89%AB%E6%96%B9%E5%90%91%22%5D%0A%20%20PROXY%20--%3E%20CHECK%7B%22%E4%B8%A4%E4%B8%AA%E8%A7%84%E6%A8%A1%E6%96%B9%E5%90%91%E4%B8%80%E8%87%B4%EF%BC%9F%22%7D%0A%20%20CHECK%20--%3E%7C%E5%90%A6%7C%20RE%5B%22%E5%9B%9E%E4%BB%A3%E7%90%86%E9%87%8D%E6%9F%A5%E5%88%B6%E5%BA%A6%E5%B7%AE%22%5D%0A%20%20CHECK%20--%3E%7C%E6%98%AF%7C%20MIX%5B%22%E9%85%8D%E6%AF%94%E5%AE%9A%E7%89%88%E5%85%A5%E5%BA%93%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[l(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[l("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,"小模型放大「合成更好学」的偏差：高密度合成去噪充分、密度均匀，训练损失与开发集都更好看，但合成分布与真实分布的缝隙在日志里不可见——这正是预训练侧「合成往往更好学，日志会骗人」的结论。小模型把这口陷阱挖得更深，因为它的容量不足以在外部保留真实分布的对照，所以小模型评测里真实探针的权重必须更高：日志选型、探针定案。蒸馏配比的特殊性在于教师链已经替你做了一层质量与难度过滤，蒸馏数据与自合成数据不是同一类资产——前者继承教师分布的偏置，后者叠加本模型的偏置，两类份额要分开记账，混在「合成」一个桶里会互相掩盖各自的上限。",-1)),E[5]||(E[5]=a("p",null,[a("span",{class:"marginnote"},"DeepSeek-R1 的蒸馏系列是配比第一性的例证：约八十万条过滤后的教师长链直接 SFT，小模型推理大幅越线，全程无需 RL。第一步永远是把教师与过滤器选对，其次才是调百分比。")],-1)),(A(),i(s,null,{default:e(()=>[r(B,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E6%95%99%E5%B8%88%E6%A8%A1%E5%9E%8B%22%5D%20--%3E%20DC%5B%22%E6%95%99%E5%B8%88%E9%95%BF%E9%93%BE%EF%BC%9A%E8%87%AA%E5%B8%A6%E8%B4%A8%E9%87%8F%E4%B8%8E%E9%9A%BE%E5%BA%A6%E8%BF%87%E6%BB%A4%22%5D%0A%20%20DC%20--%3E%7C%E7%BB%A7%E6%89%BF%E6%95%99%E5%B8%88%E5%88%86%E5%B8%83%E7%9A%84%E5%81%8F%E7%BD%AE%7C%20DIS%5B%22%E8%92%B8%E9%A6%8F%E6%A1%B6%22%5D%0A%20%20STU%5B%22%E5%AD%A6%E7%94%9F%E8%87%AA%E9%87%87%E6%A0%B7%22%5D%20--%3E%20SF%5B%22%E7%AD%94%E6%A1%88%E8%BF%87%E6%BB%A4%E5%90%8E%E5%9B%9E%E7%82%89%22%5D%0A%20%20SF%20--%3E%7C%E5%8F%A0%E5%8A%A0%E6%9C%AC%E6%A8%A1%E5%9E%8B%E8%87%AA%E5%B7%B1%E7%9A%84%E5%81%8F%E7%BD%AE%7C%20SELF%5B%22%E8%87%AA%E5%90%88%E6%88%90%E6%A1%B6%22%5D%0A%20%20DIS%20--%3E%20ACC%5B%22%E5%88%86%E5%BC%80%E8%AE%B0%E8%B4%A6%EF%BC%9A%E4%BB%BD%E9%A2%9D%E4%B8%8E%E4%B8%8A%E9%99%90%E5%90%84%E8%87%AA%E8%AE%BE%22%5D%0A%20%20SELF%20--%3E%20ACC%0A%20%20ACC%20--%3E%20PROBE%5B%22%E7%9C%9F%E5%AE%9E%E6%8E%A2%E9%92%88%E5%AE%9A%E6%A1%88%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[l(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=t('<p><span class="marginnote">这张图回答的问题是：蒸馏桶与自合成桶的偏置从哪来。蒸馏数据的质量闸在教师侧，偏置也是教师的；自合成数据的偏置来自学生自己——它的错误会被自己的过滤器放行。两类资产混记在「合成」一个桶里，各自的上限就互相掩盖了。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>配比结论的时效以教师与基座的换代为界：基座换版，旧配比的最优点整体作废，能继承的只有结构——域份额的相对次序与阶段形状。验证弱域的合成占比没有安全上界公式，只有探针增量这一个裁判。蒸馏数据的许可与教师条款是配比之外的闸门，本课程后面有专课；此处只立规矩：配比表里每一份都要能回答「从哪来、谁生成、凭什么能用」。小模型的多轮与 agent 能力配比本课不展开——它们的上限更多卡在任务与环境，不在数据百分比。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>小模型对噪声更不宽容、对风格吸收更深：过滤更紧、教师份额记账。</li><li>配比三粒度：能力域、训练阶段、教师版本；末段真实退火。</li><li>合成更好学会骗日志：真实探针权重必须更高。</li><li>蒸馏数据与自合成数据分开记账，偏置来源不同。</li><li>代理扫配比要跨两个规模验方向，防制度差假阳性。</li><li>出处：Mukherjee 等 Orca 2023；Gunasekar 等 2023；Abdin 等 Phi-3 2024；DeepSeek-AI R1 2025。</li></ul>',5))])}const T=n(m,[["render",p]]);export{f as __pageData,T as default};
